// Rebuilds src/lib/reactBitsCatalog.js, the list of free React Bits
// components shown on Settings → Connectors → React Bits:
//   node scripts/react-bits-catalog.js
//
// Only names, one-line descriptions, page links and the licence text are kept
// here. The
// components' source is never bundled with AppBlips: React Bits' licence (MIT +
// Commons Clause) forbids redistributing the components themselves, so the
// source is downloaded from reactbits.dev when a request names a component
// (electron/server/reactBitsApi.js), the same way React Bits' own shadcn
// command fetches it into a project.
//
// The list is React Bits' public shadcn registry (everything in it is free;
// Pro content isn't published there), joined with its sitemap for each
// component's page. Kept: components with a preview page. Left out: the Sound
// Lab sounds (Sound*), which share one tool page instead.
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const REGISTRY = 'https://reactbits.dev/r/registry.json';
const SITEMAP = 'https://reactbits.dev/sitemap.xml';
const LICENSE = 'https://raw.githubusercontent.com/DavidHDev/react-bits/main/LICENSE.md';
const OUT = fileURLToPath(new URL('../src/lib/reactBitsCatalog.js', import.meta.url));
const CATEGORIES = ['text-animations', 'animations', 'components', 'backgrounds', 'micro'];

const get = async (url) => {
  const response = await fetch(url, { headers: { 'user-agent': 'AppBlips catalog script' } });
  if (!response.ok) throw new Error(`${url}: HTTP ${response.status}`);
  return response.text();
};

const kebab = (name) => name.replace(/(?<=[a-z0-9])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])/g, '-').toLowerCase();
// "FlyingButton" -> "Flying Button", "ASCIIText" -> "ASCII Text".
const words = (name) => name.replace(/(?<=[a-z0-9])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])/g, ' ');

const registry = JSON.parse(await get(REGISTRY));
const pages = new Map();
for (const [, url] of (await get(SITEMAP)).matchAll(/<loc>([^<]+)<\/loc>/g)) {
  const { pathname } = new URL(url);
  const [, category, slug] = pathname.split('/');
  if (CATEGORIES.includes(category) && slug) pages.set(slug, pathname);
}

const seen = new Map();
const skipped = [];
for (const item of registry.items) {
  const match = /^([A-Za-z0-9]+)-JS-CSS$/.exec(item.name);
  if (!match || match[1].startsWith('Sound')) continue;
  const id = match[1];
  const path = pages.get(kebab(id));
  if (!path) { skipped.push(id); continue; }
  seen.set(id, {
    id,
    title: words(id),
    category: path.split('/')[1],
    path,
    description: String(item.description || '').replace(/\s+/g, ' ').trim(),
  });
}

// The licence goes into every export that holds React Bits code, and its
// copyright line above each component (lib/reactBits.js), as it requires.
const license = (await get(LICENSE)).trim();
const copyright = /^Copyright \(c\) .+$/m.exec(license)?.[0];
if (!copyright) throw new Error('No copyright line found in the React Bits licence.');
// It goes inside an HTML comment in single-file exports.
if (license.includes('--')) throw new Error('The React Bits licence now contains "--"; update withReactBitsLicense in lib/reactBits.js.');

const components = [...seen.values()].sort((a, b) => a.title.localeCompare(b.title));
writeFileSync(OUT, `// Generated by scripts/react-bits-catalog.js from React Bits' public registry
// and sitemap. Don't edit by hand: run \`node scripts/react-bits-catalog.js\`.
// Names, descriptions, page links and the licence; the source is downloaded on demand
// (see the script for why).
export const REACT_BITS_COPYRIGHT = ${JSON.stringify(copyright)};
export const REACT_BITS_LICENSE_URL = 'https://github.com/DavidHDev/react-bits/blob/main/LICENSE.md';
export const REACT_BITS_LICENSE = ${JSON.stringify(license)};
export const REACT_BITS_CATALOG = ${JSON.stringify(components, null, 1)};
`);
console.log(`Wrote ${components.length} components to ${OUT}`);
if (skipped.length) console.log(`No preview page, left out: ${skipped.join(', ')}`);
